node smoke.ts && node --input-type=module - <<'EOF'
import assert from 'node:assert/strict';
import { retryCents } from './impl.ts';
const base = { id: 'd1', customerId: 'c1', amountCents: 1001, feeCents: 30, decline: 'soft', attempt: 1 };
const history = { customerId: 'c1', attempts: [] };
assert.equal(retryCents(base, history), 1031);
assert.equal(retryCents({ ...base, attempt: 2 }, history), 1031);
assert.equal(retryCents({ ...base, attempt: 3 }, history), 530);
assert.equal(retryCents({ ...base, attempt: 4 }, history), 0);
assert.equal(retryCents({ ...base, decline: 'hard' }, history), 0);
assert.equal(retryCents(base, { ...history, customerId: 'other' }), 0);
console.log('ticket checks passed');
EOF
